import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-organic-chemistry-functional-groups-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`Rank the oxidation states of carbon-oxygen functional groups (least → most oxidized).`]: {
    question: r`In the liver, ethanol (CH₃CH₂OH) is converted to acetaldehyde (CH₃CHO) and then to acetate (CH₃COO⁻). Across these two steps, carbon 1 is:`,
    options: [r`reduced twice: 3, then 2, then 1 bonds to oxygen`, r`oxidized, then reduced: 1, then 2, then 1 bonds`, r`oxidized twice: 1, then 2, then 3 bonds to oxygen`, r`reduced, then oxidized: 2, then 1, then 3 bonds`],
    correctAnswer: 2,
    explanation: r`Count carbon 1's bonds to oxygen: one in the alcohol, two in the aldehyde (C=O counts twice) and three in the carboxylate. Each step adds a C–O bond, so both are oxidations. The other choices either run the ladder backward or miscount the bonds in the aldehyde.`,
  },
  [r`How do amines behave as bases and nucleophiles?`]: {
    question: r`Methylamine (CH₃NH₂), ammonia and aniline (C₆H₅NH₂) are each dissolved in water at the same concentration. Which solution has the highest pH, and why?`,
    options: [r`Aniline: its benzene ring donates to a localized lone pair`, r`Methylamine: its alkyl group donates to a localized lone pair`, r`Ammonia: with no carbon groups, its lone pair is most exposed`, r`Aniline: its lone pair is spread into the ring and more reactive`],
    correctAnswer: 1,
    explanation: r`The strongest base gives the highest pH. An aliphatic amine beats ammonia because the alkyl group pushes electron density toward a lone pair that stays on nitrogen. Aniline is the weakest of the three, since its lone pair is delocalized into the ring and is less available, not more.`,
  },
  [r`What functional groups result from oxidizing 1° vs 2° vs 3° alcohols?`]: {
    question: r`Three alcohols are each heated with excess chromic acid, a strong oxidant: 1-butanol, 2-butanol and 2-methyl-2-propanol. The organic products are, in that order:`,
    options: [r`butanoic acid, 2-butanone, and no reaction`, r`butanal, 2-butanone, and no reaction`, r`butanoic acid, no reaction, and 2-butanone`, r`butanal, butanoic acid, and 2-butanone`],
    correctAnswer: 0,
    explanation: r`A strong oxidant carries a primary alcohol past the aldehyde to the carboxylic acid, and takes a secondary alcohol to a ketone. The tertiary alcohol has no hydrogen on its carbinol carbon, so it does not react. Stopping at butanal describes a mild oxidant such as PCC, and the other choices swap the secondary and tertiary outcomes.`,
  },
  [r`How can you identify a carboxylic acid by a simple chemical test?`]: {
    question: r`Two unlabeled solids are benzoic acid (pKa about 4) and 2-naphthol, a phenol (pKa about 10). Each is added to aqueous NaHCO₃ and, separately, to aqueous NaOH. What is seen?`,
    options: [r`Only 2-naphthol fizzes in NaHCO₃; both dissolve in NaOH`, r`Both solids fizz in NaHCO₃; only one dissolves in NaOH`, r`Only benzoic acid fizzes in NaHCO₃; neither dissolves in NaOH`, r`Only benzoic acid fizzes in NaHCO₃; both dissolve in NaOH`],
    correctAnswer: 3,
    explanation: r`Bicarbonate is basic enough to deprotonate a carboxylic acid, forming carbonic acid that releases CO₂, but not a phenol with pKa near 10. Hydroxide is a much stronger base and deprotonates both, so both dissolve as salts. The wrong choices either give the phenol the fizz or forget that NaOH ionizes both compounds.`,
  },
  [r`Rank the functional group priority for IUPAC naming (highest to lowest).`]: {
    question: r`The compound CH₃COCH₂CH₂COOH contains a ketone and a carboxylic acid. Its IUPAC name is:`,
    options: [r`2-oxopentanoic acid`, r`4-carboxybutan-2-one`, r`pentan-2-on-5-oic acid`, r`4-oxopentanoic acid`],
    correctAnswer: 3,
    explanation: r`The carboxylic acid outranks the ketone, so it supplies the suffix and its carbon is C1; the ketone becomes the prefix oxo at C4. Calling it 2-oxo numbers from the wrong end, and the two names ending in one treat the ketone as the principal group.`,
  },
  [r`How do you tell an ester, an ether, and an anhydride apart by structure?`]: {
    question: r`Classify these three compounds in the order given: (CH₃CO)₂O, CH₃CH₂OCH₂CH₃ and CH₃COOCH₂CH₃.`,
    options: [r`ester, ether, anhydride`, r`anhydride, ether, ester`, r`anhydride, ester, ether`, r`ether, anhydride, ester`],
    correctAnswer: 1,
    explanation: r`The first has two carbonyls flanking one oxygen, which is an anhydride. The second has an oxygen between two alkyl carbons and no carbonyl, an ether. The third has one carbonyl next to an O–R, an ester. The other orders come from not counting how many carbonyls sit beside the bridging oxygen.`,
  },
  [r`Rank the acidity of common functional groups (most to least acidic).`]: {
    question: r`A chemist wants to deprotonate the terminal alkyne 1-hexyne (pKa about 25) essentially completely. Two bases are available: NaOH (conjugate acid water, pKa about 16) and NaNH₂ (conjugate acid NH₃, pKa about 38). Which will work?`,
    options: [r`NaOH only: its conjugate acid is stronger than the alkyne`, r`NaNH₂ only: its conjugate acid is weaker than the alkyne`, r`Both: each conjugate acid has a pKa well away from 25`, r`Neither: a C–H bond is never acidic enough to deprotonate`],
    correctAnswer: 1,
    explanation: r`A base removes a proton fully only when its conjugate acid is weaker (higher pKa) than the acid it attacks. Ammonia at 38 is weaker than the alkyne at 25, so amide ion works, while water at 16 is a stronger acid than the alkyne, so hydroxide does not. Choosing NaOH flips the comparison, and a terminal alkyne C–H is acidic enough for a strong base.`,
  },
  [r`Which functional groups can hydrogen-bond, and how does that show up in boiling points?`]: {
    question: r`Pentane, butanal and 1-butanol all have molar masses of 72 to 74 g/mol. Ranked from lowest to highest boiling point, they are:`,
    options: [r`butanal < pentane < 1-butanol`, r`pentane < 1-butanol < butanal`, r`1-butanol < butanal < pentane`, r`pentane < butanal < 1-butanol`],
    correctAnswer: 3,
    explanation: r`Pentane has only dispersion forces, butanal adds a polar carbonyl that can accept but not donate hydrogen bonds, and 1-butanol has an O–H that donates them to its neighbors. Boiling point rises in that order. The wrong orders either rate the carbonyl above an O–H or treat hydrogen bonding as lowering the boiling point.`,
  },
  [r`A hemiacetal forms from an aldehyde plus:`]: {
    question: r`Acetaldehyde (CH₃CHO) reacts with exactly one equivalent of methanol under acid catalysis. In the product, the former carbonyl carbon is bonded to:`,
    options: [r`two OCH₃ groups, one H and one CH₃`, r`two OH groups, one H and one CH₃`, r`one OH, one OCH₃, one H and one CH₃`, r`one OCH₃, one =O and one CH₃`],
    correctAnswer: 2,
    explanation: r`One alcohol adds across the C=O to give a hemiacetal: the carbon keeps its H and CH₃ and gains an OH and an OCH₃. Two OCH₃ groups would be the acetal, which needs a second equivalent of methanol. Two OH groups is the hydrate formed with water, and the choice that keeps C=O is an ester, a higher oxidation level.`,
  },
  [r`Which functional group is most water-soluble at physiological pH?`]: {
    question: r`Hexanoic acid, CH₃(CH₂)₄COOH, is only slightly soluble in water at pH 2 but dissolves readily at pH 7.4. The best explanation is that at pH 7.4 it is:`,
    options: [r`protonated to a charged oxonium ion that water hydrates well`, r`hydrolyzed to shorter neutral pieces that water hydrates well`, r`deprotonated to a charged carboxylate that water hydrates well`, r`reduced to a neutral alcohol that hydrogen bonds to water well`],
    correctAnswer: 2,
    explanation: r`With a pKa near 5, the acid is neutral at pH 2 and almost entirely the carboxylate anion at pH 7.4, and ion-dipole hydration of the charge pulls the six-carbon chain into solution. Raising the pH removes protons rather than adding them, and a pH change neither cleaves the chain nor reduces the acid.`,
  },
  [r`Which amino acid has an aromatic R-group that absorbs UV light at 280 nm?`]: {
    question: r`A protein contains two tryptophans and several tyrosines. A mutant replaces both tryptophans with leucine and leaves the tyrosines alone. At the same protein concentration, the mutant's absorbance at 280 nm will:`,
    options: [r`rise sharply, since leucine side chains absorb more strongly`, r`stay the same, since peptide bonds supply the 280 nm signal`, r`fall sharply, since the indole rings absorbed most strongly`, r`fall to zero, since only tryptophan can absorb at 280 nm`],
    correctAnswer: 2,
    explanation: r`Tryptophan's indole ring is the strongest absorber at 280 nm, so removing it drops the signal a great deal. It does not reach zero because tyrosine also absorbs there. Leucine has no aromatic ring and does not absorb at 280 nm, and peptide bonds absorb much deeper in the UV.`,
  },
  [r`Rank acidity: phenol, ethanol, acetic acid.`]: {
    question: r`Sodium phenoxide (phenol pKa about 10) is mixed with acetic acid (pKa about 5) in one flask and with ethanol (pKa about 16) in another. In which flask is phenoxide converted almost completely to phenol?`,
    options: [r`The acetic acid flask only: pKa 5 is below phenol's 10`, r`The ethanol flask only: pKa 16 is above phenol's 10`, r`Both flasks: each O–H is more acidic than phenol's O–H`, r`Neither flask: phenoxide is too weak a base to take a proton`],
    correctAnswer: 0,
    explanation: r`Proton transfer runs from the stronger acid to the conjugate base of the weaker one. Acetic acid is a stronger acid than phenol, so it protonates phenoxide; ethanol is weaker than phenol, so it does not. The wrong choices reverse the order acetic acid > phenol > ethanol.`,
  },
  [r`Which functional group is found in all amino acids?`]: {
    question: r`Free leucine has a side chain made only of carbon and hydrogen. When it is titrated from pH 1 to pH 12, how many groups lose a proton, and which are they?`,
    options: [r`None: a hydrocarbon side chain cannot ionize`, r`One: only the α-carboxyl group loses a proton`, r`Two: the α-carboxyl group and the α-amino group`, r`Three: carboxyl, amino and the side chain`],
    correctAnswer: 2,
    explanation: r`Every amino acid carries both an amino group and a carboxyl group on its α-carbon, whatever the side chain is, so leucine shows two ionizations. Answering none or one forgets a backbone group, and answering three credits the hydrocarbon side chain with a proton it cannot lose.`,
  },
  [r`Rank reactivity toward nucleophilic acyl substitution (most to least):`]: {
    question: r`Which of these conversions goes readily in one step, with no activating reagent, because it moves down the acyl reactivity series?`,
    options: [r`acetyl chloride + ethanol → ethyl acetate`, r`acetamide + ethanol → ethyl acetate`, r`ethyl acetate + chloride → acetyl chloride`, r`acetamide + acetate → acetic anhydride`],
    correctAnswer: 0,
    explanation: r`The order is acid chloride > anhydride > ester > amide, and substitution runs easily only from a more reactive derivative to a less reactive one. Acid chloride to ester goes downhill. The other three all try to climb the series, from an amide to an ester or anhydride or from an ester to an acid chloride.`,
  },
  [r`What is the priority order for IUPAC suffix naming (highest first)?`]: {
    question: r`The compound CH₃COCH₂CH₂OH contains a ketone and an alcohol. Its IUPAC name is:`,
    options: [r`3-oxobutan-1-ol`, r`1-hydroxybutan-3-one`, r`4-hydroxybutan-2-one`, r`2-oxobutan-4-ol`],
    correctAnswer: 2,
    explanation: r`A ketone outranks an alcohol, so the ketone supplies the suffix and gets the lowest possible number (C2), and the OH becomes a hydroxy prefix at C4. The two names ending in ol make the lower-priority alcohol the principal group, and 1-hydroxybutan-3-one numbers from the wrong end.`,
  },
  [r`Which boils higher, propylamine or trimethylamine, and why?`]: {
    question: r`Propylamine, ethylmethylamine and trimethylamine are all C₃H₉N. Which has the lowest boiling point, and why?`,
    options: [r`Propylamine: its straight chain has the least surface contact`, r`Trimethylamine: it has the lowest molar mass of the three`, r`Trimethylamine: with no N–H it cannot donate hydrogen bonds`, r`Propylamine: its two N–H bonds repel neighboring molecules`],
    correctAnswer: 2,
    explanation: r`The three are isomers with the same mass, so the difference is hydrogen bonding. The tertiary amine has no N–H and can only accept hydrogen bonds, so its molecules hold together least. Propylamine has two N–H bonds that attract neighbors, and it boils highest, not lowest.`,
  },
  [r`Chloroacetic acid has $pK_a$ 2.9 versus 4.8 for acetic acid, a shift driven entirely by {{c1::the inductive effect}}.`]: {
    question: r`Rank these acids from strongest to weakest: propanoic acid (CH₃CH₂COOH), 2-chloropropanoic acid (CH₃CHClCOOH) and 3-chloropropanoic acid (ClCH₂CH₂COOH).`,
    options: [r`2-chloropropanoic > 3-chloropropanoic > propanoic`, r`3-chloropropanoic > 2-chloropropanoic > propanoic`, r`propanoic > 3-chloropropanoic > 2-chloropropanoic`, r`2-chloropropanoic > propanoic > 3-chloropropanoic`],
    correctAnswer: 0,
    explanation: r`Chlorine pulls electron density through the sigma bonds and stabilizes the carboxylate, and this inductive effect fades with each extra bond. So the chlorine one carbon from the carboxyl helps most, the one two carbons away helps less, and the unsubstituted acid is weakest. The other orders put the farther chlorine ahead or treat chlorine as weakening the acid.`,
  },
  [r`Aldehydes are more reactive than ketones toward nucleophilic addition for which two reasons?`]: {
    question: r`4-Oxopentanal, CH₃COCH₂CH₂CHO, is treated with one equivalent of a nucleophile. Where does most of the attack occur, and why?`,
    options: [r`C1, the aldehyde: less crowded and more electron-poor`, r`C4, the ketone: two alkyl groups make it more electron-poor`, r`C1, the aldehyde: its C–H bond donates extra electron density`, r`C4, the ketone: two alkyl groups open more room for attack`],
    correctAnswer: 0,
    explanation: r`The aldehyde carbon has only one alkyl group, so it is less hindered and gets less electron donation, leaving a larger partial positive charge. Alkyl groups on the ketone donate electrons and add crowding, which is the opposite of what the ketone choices claim. The aldehyde is favored because it is electron-poor, not because of donation from its C–H.`,
  },
  [r`The anomeric carbon of a cyclic monosaccharide is a {{c1::hemiacetal}} carbon.`]: {
    question: r`In the ring form of glucose (glucopyranose), which carbon is bonded to both the ring oxygen and a free OH, and what does that allow?`,
    options: [r`C1: the ring can open, so α and β forms interconvert`, r`C5: the ring can open, so α and β forms interconvert`, r`C1: the ring is locked, so α and β forms cannot interconvert`, r`C2: the ring can open, so D and L forms interconvert`],
    correctAnswer: 0,
    explanation: r`C1, the anomeric carbon, carries one OR (the ring oxygen) and one OH, which makes it a hemiacetal. Hemiacetal formation is reversible, so the ring opens and recloses to either anomer (mutarotation). C5 supplies the ring oxygen but has no OH of its own, and only an acetal, not a hemiacetal, would be locked.`,
  },
  [r`A carboxylic acid with $pK_a$ 4.5 exists at physiological pH almost entirely as {{c1::the carboxylate anion}}.`]: {
    question: r`A carboxylic acid drug has a pKa of 3.5. Which forms dominate in stomach fluid at pH 1.5 and in blood at pH 7.4?`,
    options: [r`carboxylate anion in the stomach; neutral acid in blood`, r`neutral acid in the stomach; carboxylate anion in blood`, r`neutral acid in the stomach and neutral acid in blood`, r`carboxylate anion in the stomach and also in blood`],
    correctAnswer: 1,
    explanation: r`Below its pKa an acid is mostly protonated, and above its pKa it is mostly deprotonated. At pH 1.5, two units below 3.5, about 99% is the neutral acid; at pH 7.4, almost four units above, it is nearly all carboxylate. The other choices reverse this rule or ignore the change in pH.`,
  },
  [r`Ethanethiol ($pK_a$ ~10) far outstrips ethanol ($pK_a$ ~16) in acidity because sulfur is {{c1::larger and more polarizable}}.`]: {
    question: r`Oxygen is more electronegative than sulfur, yet ethanethiol is a stronger acid than ethanol. Which other comparison is explained by the same principle?`,
    options: [r`HI beats HF: the charge sits on a larger, more polarizable atom`, r`HF beats CH₄: the charge sits on a more electronegative atom`, r`Acetic acid beats ethanol: resonance shares charge over two atoms`, r`Chloroacetic beats acetic acid: charge is pulled through σ bonds`],
    correctAnswer: 0,
    explanation: r`Thiolate is more stable than alkoxide because sulfur is larger and more polarizable, so the negative charge is spread over more volume. The same size effect down a group makes HI stronger than HF. The other comparisons are all true, but they rest on electronegativity across a row, resonance and induction.`,
  },
  [r`Anilinium has $pK_a$ ~4.6 while cyclohexylammonium has $pK_a$ ~10.6. What makes aniline such a weak base?`]: {
    question: r`Anilinium has a pKa of about 4.6 and cyclohexylammonium about 10.6. Which amine is the stronger base, by roughly what factor, and why?`,
    options: [r`Aniline, by about 10⁶: its lone pair is spread into the ring`, r`Cyclohexylamine, by about 6 times: its lone pair is localized`, r`Aniline, by about 6 times: its lone pair is spread into the ring`, r`Cyclohexylamine, by about 10⁶: its lone pair is localized on N`],
    correctAnswer: 3,
    explanation: r`The higher the pKa of the conjugate acid, the stronger the base, and a gap of 6 pKa units is a factor of 10⁶, not 6. Cyclohexylamine's lone pair stays on nitrogen and is free to take a proton. Aniline's lone pair is delocalized into the ring, which makes it less available, so aniline is the weaker base.`,
  },
  [r`An amide nitrogen is not basic; protonation of an amide happens instead at the {{c1::carbonyl oxygen}}.`]: {
    question: r`Acid-catalyzed hydrolysis of acetamide (CH₃CONH₂) begins with protonation of the amide. Which first step is correct, and how does it help water attack?`,
    options: [r`N is protonated, which lets ammonia leave before water arrives`, r`O is protonated, which makes the carbonyl carbon more electrophilic`, r`N is protonated, which makes the carbonyl carbon less electrophilic`, r`C is protonated, which makes the carbonyl oxygen more nucleophilic`],
    correctAnswer: 1,
    explanation: r`The amide nitrogen's lone pair is tied up in resonance with the C=O, so the basic site is the carbonyl oxygen, and protonating it keeps that delocalization. An O-protonated carbonyl is a much better electrophile for water. Protonating nitrogen is the expected amine behavior, but it does not happen first in an amide, and the carbonyl carbon has no lone pair to protonate.`,
  },
  [r`Carboxylic acids boil anomalously high because they form {{c1::hydrogen-bonded cyclic dimers}}.`]: {
    question: r`Acetic acid has a molar mass of 60 g/mol, but a measurement of how many particles it forms in benzene gives an apparent molar mass near 120 g/mol. The best explanation is that:`,
    options: [r`each molecule splits into two ions that act as separate particles`, r`two molecules joined by a covalent anhydride bond have lost water`, r`two molecules joined by two hydrogen bonds act as one particle`, r`each molecule adds to benzene to form one heavier ester particle`],
    correctAnswer: 2,
    explanation: r`Carboxylic acids pair up as cyclic dimers held by two hydrogen bonds, so in a nonpolar solvent each particle weighs twice the formula mass. Ionizing would give more particles and an apparent mass below 60, not above. No covalent reaction occurs: an anhydride would weigh 102, and acetic acid does not add to benzene.`,
  },
  [r`Branching {{c1::lowers}} boiling point because it {{c2::reduces surface area for dispersion contact}}.`]: {
    question: r`1-Butanol boils at 118 °C and its isomer 2-methyl-2-propanol (tert-butanol) at 82 °C. Each has one O–H. The lower boiling point of tert-butanol is best explained by:`,
    options: [r`its compact shape, which gives more surface for dispersion contact`, r`its tertiary carbon, which stops the O–H from hydrogen bonding`, r`its branching, which gives it a lower molar mass than 1-butanol`, r`its compact shape, which gives less surface for dispersion contact`],
    correctAnswer: 3,
    explanation: r`Branching makes a molecule more compact, so it touches its neighbors over less area and has weaker dispersion forces. That lowers the boiling point even though both isomers hydrogen bond. Isomers have the same molar mass, and a tertiary alcohol still has an O–H that hydrogen bonds.`,
  },
  [r`A primary amine plus a ketone yields an {{c1::imine}}, while a secondary amine yields an {{c2::enamine}}.`]: {
    question: r`Cyclohexanone is heated with pyrrolidine, a secondary amine (a five-membered ring containing N–H), with acid catalysis and removal of water. The product contains:`,
    options: [r`a C=N bond with a neutral nitrogen bearing no hydrogen`, r`a C=O bond with nitrogen attached to the carbonyl carbon`, r`a C=C bond with nitrogen attached to one of its carbons`, r`a C–N bond with an OH still on that same carbon`],
    correctAnswer: 2,
    explanation: r`A secondary amine has only one N–H, which is lost in forming the iminium ion, so the last proton must come from the α-carbon, giving an enamine, with nitrogen on an alkene carbon. A neutral C=N imine needs a primary amine with a second N–H to lose. An amide is a different oxidation level, and the carbinolamine with OH still attached is only an intermediate once water is removed.`,
  },
  [r`Tosylate is an outstanding leaving group because its conjugate acid is {{c1::a strong sulfonic acid}}.`]: {
    question: r`Three primary alkyl substrates differ only in leaving group: hydroxide (conjugate acid pKa about 16), acetate (about 5) and tosylate (about −3). With the same nucleophile, the order of substitution rate, fastest first, is:`,
    options: [r`tosylate > acetate > hydroxide`, r`hydroxide > acetate > tosylate`, r`acetate > tosylate > hydroxide`, r`tosylate > hydroxide > acetate`],
    correctAnswer: 0,
    explanation: r`A good leaving group is a weak base, which means its conjugate acid is strong (low pKa). Toluenesulfonic acid is the strongest acid of the three, so tosylate leaves best, then acetate, and hydroxide is the worst. The reversed order treats the strongest base as the best leaving group.`,
  },
  [r`Which functional group produces the very broad IR absorption spanning 2500 to 3500 cm$^{-1}$?`]: {
    question: r`An unknown with formula C₃H₆O₂ shows a strong IR band at 1710 cm⁻¹ and a very broad absorption running from 2500 to 3500 cm⁻¹ that covers the C–H stretches. It is most likely:`,
    options: [r`methyl acetate, CH₃COOCH₃`, r`ethyl formate, HCOOCH₂CH₃`, r`hydroxyacetone, CH₃COCH₂OH`, r`propanoic acid, CH₃CH₂COOH`],
    correctAnswer: 3,
    explanation: r`A very broad band from 2500 to 3500 cm⁻¹ together with a carbonyl near 1710 is the signature of a carboxylic acid O–H in its hydrogen-bonded dimer. The two esters have no O–H at all and absorb near 1740. Hydroxyacetone has an alcohol O–H, which gives a narrower band centered near 3400 that does not reach down to 2500.`,
  },
  [r`In nucleophilic acyl substitution, the more stable the leaving group, the {{c1::more reactive}} the acyl derivative.`]: {
    question: r`Leaving groups and the pKa of their conjugate acids: chloride (−7), carboxylate (5), alkoxide (16) and amide ion (38). A phenyl ester has phenoxide as its leaving group (conjugate acid pKa 10). Its reactivity in acyl substitution should fall:`,
    options: [r`between an acid chloride and an anhydride`, r`between an anhydride and an ordinary alkyl ester`, r`between an ordinary alkyl ester and an amide`, r`below an amide, as the least reactive of all`],
    correctAnswer: 1,
    explanation: r`The more stable the leaving group (the lower its conjugate acid's pKa), the more reactive the acyl derivative. A pKa of 10 lies between carboxylate at 5 (the anhydride) and alkoxide at 16 (the alkyl ester), so the phenyl ester sits between those two. The other placements put pKa 10 in the wrong gap of the series.`,
  },
  [r`A beta-keto ester has an alpha-carbon $pK_a$ near {{c1::11}}, versus roughly {{c2::25}} for a simple ester.`]: {
    question: r`Ethyl acetoacetate is CH₃–CO–CH₂–CO–OCH₂CH₃, numbered with the ester carbonyl as C1. One equivalent of sodium ethoxide removes which hydrogen?`,
    options: [r`One on C4, the CH₃ next to the ketone carbonyl only`, r`One on C2, the CH₂ flanked by both carbonyl groups`, r`One on the OCH₂ carbon of the ethyl ester group`, r`One on the terminal CH₃ of the ethyl ester group`],
    correctAnswer: 1,
    explanation: r`The C2 hydrogens have a pKa near 11 because the enolate is delocalized over two carbonyls, so ethoxide (ethanol pKa about 16) removes one completely. The C4 hydrogens are α to only one carbonyl (pKa about 20) and are far less acidic. The hydrogens of the ethyl group are not α to any carbonyl and are not acidic.`,
  },
  [r`In water, amine basicity runs secondary above primary above tertiary rather than tracking alkyl donation. Why?`]: {
    question: r`In the gas phase trimethylamine is a stronger base than dimethylamine, but in water the order reverses (conjugate acid pKa 9.8 versus 10.7). The reversal in water arises because:`,
    options: [r`(CH₃)₃NH⁺ has three N–H bonds, so water binds it too tightly`, r`(CH₃)₃NH⁺ has one N–H, so water stabilizes it poorly`, r`methyl groups withdraw electron density once in water`, r`(CH₃)₃N has no lone pair on nitrogen once it dissolves`],
    correctAnswer: 1,
    explanation: r`Alkyl groups donate electron density, which is why the tertiary amine wins in the gas phase. In water the ammonium ion must also be solvated through its N–H bonds, and the trialkylammonium ion has only one, so it is the least stabilized. Methyl groups do not become withdrawing in water, and the nitrogen keeps its lone pair.`,
  },
  [r`Roughly how many carbons can a molecule with one hydrogen-bonding group carry and still dissolve in water?`]: {
    question: r`During an extraction, a chemist needs an alcohol that will stay out of the aqueous layer. Using the rule of thumb for how much carbon one hydrogen-bonding group can carry into water, the best choice is:`,
    options: [r`1-propanol, CH₃(CH₂)₂OH`, r`1,2-ethanediol, HOCH₂CH₂OH`, r`1-octanol, CH₃(CH₂)₇OH`, r`2-propanol, (CH₃)₂CHOH`],
    correctAnswer: 2,
    explanation: r`One hydrogen-bonding group can carry roughly four to five carbons into water. 1-Octanol has eight carbons on a single OH, so the hydrocarbon part dominates and it stays out of water. The three-carbon alcohols and the two-carbon diol are well under the limit and mix freely with water.`,
  },
  [r`In extraction, aqueous {{c1::$NaHCO_3$}} deprotonates carboxylic acids but leaves phenols neutral in the organic layer.`]: {
    question: r`An ether solution holds benzoic acid (pKa about 4), 2-naphthol (a phenol, pKa about 10) and naphthalene. Which sequence of aqueous washes puts each compound in its own fraction?`,
    options: [r`NaOH first to take the acid, then NaHCO₃ to take the naphthol`, r`NaHCO₃ first to take the naphthol, then NaOH to take the acid`, r`HCl first to take the acid, then NaHCO₃ to take the naphthol`, r`NaHCO₃ first to take the acid, then NaOH to take the naphthol`],
    correctAnswer: 3,
    explanation: r`Bicarbonate is a weak base that deprotonates only the carboxylic acid, so it must come first; hydroxide then deprotonates the phenol, and naphthalene stays in the ether. Using NaOH first would pull the acid and the phenol out together. Bicarbonate cannot ionize a phenol, and HCl does not ionize a carboxylic acid at all.`,
  },
  [r`How do you pull an amine out of an ether layer and into the aqueous layer?`]: {
    question: r`An ether layer contains decylamine (C₁₀H₂₁NH₂), decanoic acid and decane. Which single aqueous wash moves only the amine into the water layer?`,
    options: [r`Dilute HCl, which turns the amine into an ammonium salt`, r`Dilute NaOH, which turns the amine into an amide anion`, r`Dilute NaHCO₃, which turns the amine into a neutral salt`, r`Pure water, which hydrogen bonds to the amine's N–H`],
    correctAnswer: 0,
    explanation: r`Acid protonates the basic amine to a charged ammonium ion that prefers water, while the neutral acid and the alkane stay in the ether. NaOH and NaHCO₃ are bases: they would ionize the carboxylic acid instead and leave the amine neutral. A ten-carbon amine is far too greasy for plain water to extract.`,
  },
  [r`The carbon oxidation ladder climbs alkane, alcohol, aldehyde, carboxylic acid, and finally {{c1::$CO_2$}}.`]: {
    question: r`Methanol is completely oxidized in the body in three successive two-electron steps. In order, the carbon passes through:`,
    options: [r`formic acid, then formaldehyde, then CO₂`, r`formaldehyde, then formic acid, then CO₂`, r`formaldehyde, then CO₂, then formic acid`, r`methane, then formaldehyde, then formic acid`],
    correctAnswer: 1,
    explanation: r`Each oxidation adds one bond from carbon to oxygen: alcohol (1), aldehyde (2), carboxylic acid (3), and finally CO₂ (4), the top of the ladder. Putting formic acid before formaldehyde or CO₂ before formic acid skips rungs. Methane lies below methanol, so reaching it would be a reduction.`,
  },
  [r`An acetal protects a ketone because acetals resist {{c1::base and nucleophiles}} yet are cleaved by {{c2::aqueous acid}}.`]: {
    question: r`Methyl 4-oxopentanoate, CH₃COCH₂CH₂COOCH₃, has a ketone and an ester. A chemist wants LiAlH₄, a strong nucleophilic hydride, to reduce only the ester. Which plan works?`,
    options: [r`Make the ketone's acetal, reduce, then remove it with aqueous base`, r`Reduce first, then make the ketone's acetal with aqueous acid`, r`Make the ketone's acetal, reduce, then remove it with aqueous acid`, r`Make the ester's acetal, reduce, then remove it with aqueous acid`],
    correctAnswer: 2,
    explanation: r`An acetal has no electrophilic carbonyl, so it survives bases and nucleophiles such as hydride, and dilute aqueous acid then regenerates the ketone. Aqueous base cannot cleave an acetal. Reducing first would destroy the more reactive ketone, and it is the group to be kept, not the ester, that must be protected.`,
  },
  [r`An epoxide is just a three-membered ether, yet it is highly reactive. What makes the difference?`]: {
    question: r`Oxirane (ethylene oxide, a three-membered cyclic ether) and tetrahydrofuran (a five-membered cyclic ether) are each stirred with a thiolate nucleophile at room temperature. What happens?`,
    options: [r`Only tetrahydrofuran reacts: its larger ring is more strained`, r`Both react: any ether oxygen is a good leaving group`, r`Neither reacts: an alkoxide can never be displaced`, r`Only oxirane reacts: opening its ring releases ring strain`],
    correctAnswer: 3,
    explanation: r`A three-membered ring carries about 27 kcal/mol of strain, and relieving it lets a nucleophile open the epoxide even though the leaving group is an alkoxide. A five-membered ether has almost no strain and behaves like an ordinary, unreactive ether. So ether oxygens are normally poor leaving groups, but the strained epoxide is the exception.`,
  },
  [r`A thioester such as acetyl-CoA outruns an oxygen ester because sulfur {{c1::donates poorly into the carbonyl}}.`]: {
    question: r`An amine attacks S-ethyl thioacetate (CH₃COSCH₂CH₃) much faster than ethyl acetate (CH₃COOCH₂CH₃). The main reason is that the thioester's carbonyl carbon is:`,
    options: [r`less electrophilic, since sulfur donates more strongly than oxygen`, r`more electrophilic, since sulfur is more electronegative than oxygen`, r`more electrophilic, since sulfur 3p overlaps poorly with carbon 2p`, r`equally electrophilic, since sulfur and oxygen share a group`],
    correctAnswer: 2,
    explanation: r`Resonance donation from the heteroatom stabilizes an ester and makes its carbonyl less electrophilic. Sulfur's larger 3p orbital overlaps poorly with carbon's 2p, so the thioester gets little of that stabilization and stays reactive; thiolate is also a better leaving group. Sulfur is less electronegative than oxygen, so electronegativity is not the reason.`,
  },
  [r`Why must an alcohol be protected before a Grignard reaction is run elsewhere in the molecule?`]: {
    question: r`A student tries to make a Grignard reagent from 4-bromo-1-butanol, BrCH₂CH₂CH₂CH₂OH, and magnesium in ether, without protecting anything. What goes wrong?`,
    options: [r`The C–Mg carbon attacks the ether solvent, consuming the reagent`, r`The O–H group oxidizes the magnesium, forming an aldehyde`, r`The O–H group displaces bromide before magnesium can insert`, r`The C–Mg carbon takes the O–H proton, destroying the reagent`],
    correctAnswer: 3,
    explanation: r`A Grignard carbon is a very strong base, and an alcohol O–H (pKa about 16) protonates it at once, leaving an alkane C–H and a magnesium alkoxide. That is why the OH is first masked, for example as a silyl ether. Ethers are inert to Grignard reagents, and a neutral OH does not oxidize magnesium or displace bromide on its own.`,
  },
  [r`Diethyl ether and THF serve as solvents because ethers are {{c1::chemically inert to acids, bases, and nucleophiles}}.`]: {
    question: r`Which liquid would be destroyed if it were used as the solvent for ethylmagnesium bromide, a strong base and nucleophile?`,
    options: [r`diethyl ether, attacked at its C–O carbon`, r`tetrahydrofuran, opened at its ring C–O bond`, r`hexane, deprotonated at one of its C–H bonds`, r`ethyl acetate, attacked at its carbonyl carbon`],
    correctAnswer: 3,
    explanation: r`Ethers are used as solvents because they are inert to bases and nucleophiles: their C–O bonds are strong and alkoxide is a very poor leaving group. An ester has an electrophilic carbonyl that the Grignard reagent attacks. Hexane has no acidic hydrogen, so it is not consumed either.`,
  },
  [r`Imine (Schiff base) chemistry underlies which two classic biological systems?`]: {
    question: r`Sodium borohydride reduces C=N bonds to C–N single bonds. Treating rhodopsin with it permanently fixes retinal, an aldehyde, to a lysine side chain of opsin. This shows that retinal was attached through:`,
    options: [r`an amide, now reduced to a stable imine`, r`an acetal, now reduced to a stable ether`, r`a thioester, now reduced to a stable thiol`, r`an imine, now reduced to a stable amine`],
    correctAnswer: 3,
    explanation: r`An aldehyde and a primary amine such as the lysine side chain condense to a C=N imine, also called a Schiff base, which is normally reversible by hydrolysis. Reducing it to an amine removes the C=N and locks the link. Lysine's amine and an aldehyde cannot form an amide, an acetal or a thioester.`,
  },
  [r`Alcohol acidity rises from tertiary to secondary to primary to methanol. What drives that trend in solution?`]: {
    question: r`In solution, potassium tert-butoxide, (CH₃)₃CO⁻ K⁺, is a stronger base than sodium methoxide, CH₃O⁻ Na⁺. The best explanation is that in tert-butoxide:`,
    options: [r`the three methyl groups pull electron density off the O⁻`, r`the bulky alkyl groups keep solvent from stabilizing the O⁻`, r`the charge is spread by resonance onto three carbons`, r`the oxygen is larger and so holds its charge more loosely`],
    correctAnswer: 1,
    explanation: r`Alcohol acidity falls from methanol to tertiary alcohols mainly because bulky groups block solvent from hydrogen bonding to the alkoxide oxygen, so the tertiary alkoxide is less stabilized and more basic. Alkyl groups donate rather than withdraw electron density. There is no resonance onto sp³ carbons, and the oxygen atom is the same size in both ions.`,
  },
  [r`Amines act as both bases and nucleophiles. Which role dominates when an amine meets a primary alkyl halide?`]: {
    question: r`Ethylamine is mixed with one equivalent of bromoethane, a primary alkyl halide. The product is a mixture containing diethylamine, triethylamine and tetraethylammonium bromide. Why?`,
    options: [r`Each new amine acts only as a base and eliminates HBr from the halide`, r`Bromide attacks the product amines and shuffles their ethyl groups`, r`The ammonium salts formed are better nucleophiles than the amines`, r`Each new amine is still a nucleophile and attacks more bromoethane`],
    correctAnswer: 3,
    explanation: r`With a primary alkyl halide an amine acts mainly as a nucleophile in substitution. The alkylated product still has a lone pair, so it attacks again, and over-alkylation continues up to the quaternary salt. Elimination is minor at a primary carbon, bromide does not dealkylate amines here, and an ammonium ion has no lone pair to attack with.`,
  },
  [r`A quaternary ammonium ion carries a permanent positive charge and {{c1::cannot be deprotonated}}.`]: {
    question: r`A tertiary amine drug (conjugate acid pKa 9) and its N-methylated quaternary ammonium analog are both in intestinal fluid at pH 8. Which can cross the membrane by passive diffusion?`,
    options: [r`Only the quaternary ion: it sheds its charge at pH 8`, r`Only the tertiary amine: part of it is neutral at pH 8`, r`Both: each is deprotonated to a neutral form at pH 8`, r`Neither: both stay fully charged at every pH value`],
    correctAnswer: 1,
    explanation: r`At pH 8 about one tenth of the tertiary amine is the neutral free base, which can diffuse across, and the equilibrium keeps resupplying it. A quaternary ammonium ion has four N–C bonds and no N–H, so it cannot be deprotonated and stays charged at any pH. Its charge is permanent, while the tertiary amine's is not.`,
  },
  [r`How does an IR spectrum distinguish an aldehyde from a ketone?`]: {
    question: r`Two unlabeled bottles hold butanal (CH₃CH₂CH₂CHO) and 2-butanone (CH₃COCH₂CH₃). Which IR observation, seen for only one bottle, identifies it as the butanal?`,
    options: [r`two weak bands near 2720 and 2820 cm⁻¹`, r`one strong band near 1715 to 1725 cm⁻¹`, r`one broad band near 3200 to 3600 cm⁻¹`, r`one sharp band near 2100 to 2250 cm⁻¹`],
    correctAnswer: 0,
    explanation: r`The hydrogen on an aldehyde's carbonyl carbon gives a pair of weak C–H stretches near 2720 and 2820 cm⁻¹, which a ketone cannot show. Both compounds have a strong carbonyl band near 1715 to 1725, so that band does not tell them apart. A broad band above 3200 is an O–H and a sharp band near 2100 to 2250 is a triple bond, and neither compound has one.`,
  },
  [r`A primary amine shows {{c1::two}} N-H stretches in the IR, whereas a secondary amine shows {{c2::one}}.`]: {
    question: r`Three isomers of C₄H₁₁N are examined by IR between 3300 and 3500 cm⁻¹. Sample X shows two bands, sample Y shows one, and sample Z shows none. X, Y and Z are, in order:`,
    options: [r`diethylamine, butylamine, N,N-dimethylethylamine`, r`N,N-dimethylethylamine, diethylamine, butylamine`, r`butylamine, diethylamine, N,N-dimethylethylamine`, r`butylamine, N,N-dimethylethylamine, diethylamine`],
    correctAnswer: 2,
    explanation: r`A primary amine (NH₂) has symmetric and asymmetric N–H stretches, so it shows two bands; a secondary amine has one N–H and one band; a tertiary amine has no N–H and no band. Butylamine is primary, diethylamine secondary and N,N-dimethylethylamine tertiary. The other orders mismatch the number of N–H bonds with the number of bands.`,
  },
  [r`Why does a carboxylic acid, but not an alcohol, dissolve in aqueous $NaHCO_3$ with visible bubbling?`]: {
    question: r`1-Hexanol added to aqueous NaHCO₃ gives two layers and no bubbles. Hexanoic acid added to the same solution fizzes and ends as one clear layer. What happened to the acid?`,
    options: [r`It was deprotonated to a soluble carboxylate, and H₂CO₃ gave CO₂`, r`It was oxidized to a soluble alcohol, and its lost carbon gave CO₂`, r`It was protonated to a soluble cation, and the OH⁻ formed gave O₂`, r`It was deprotonated to a soluble alkoxide, and the H⁺ lost gave H₂`],
    correctAnswer: 0,
    explanation: r`Bicarbonate removes the acid's proton (pKa about 5), giving a water-soluble carboxylate and carbonic acid, which breaks down to CO₂ and water. An alcohol with pKa about 16 is far too weak an acid to react, so 1-hexanol stays as its own layer. No redox occurs, a base does not protonate the acid, and the gas is CO₂ rather than O₂ or H₂.`,
  },
  [r`Alcohols, ethers, alkyl halides, and amines all sit at {{c1::the same}} carbon oxidation level.`]: {
    question: r`Which of these conversions needs neither an oxidizing agent nor a reducing agent?`,
    options: [r`1-butanol → butanal`, r`butanal → butanoic acid`, r`1-bromobutane → 1-butanol`, r`butanoic acid → 1-butanol`],
    correctAnswer: 2,
    explanation: r`An alkyl halide and an alcohol each have one bond from carbon to a heteroatom, so they sit at the same oxidation level and interconvert by substitution. Alcohol to aldehyde and aldehyde to acid each add a C–O bond, which is oxidation. Acid to alcohol removes two C–O bonds, which is reduction.`,
  },
  [r`A geminal diol, an acetal, and an aldehyde all sit at the same oxidation level. Why?`]: {
    question: r`In water, acetaldehyde (CH₃CHO) is in equilibrium with its hydrate, CH₃CH(OH)₂. How should the forward reaction be classified?`,
    options: [r`Oxidation: carbon goes from one bond to oxygen to two`, r`Reduction: carbon loses its double bond to oxygen`, r`Oxidation: carbon ends up bonded to a second oxygen atom`, r`Not redox: carbon has two bonds to oxygen before and after`],
    correctAnswer: 3,
    explanation: r`A C=O counts as two bonds to oxygen, and the geminal diol has two single C–O bonds, so the oxidation level is unchanged and hydration is a simple addition equilibrium. Calling it oxidation counts oxygen atoms instead of bonds, and calling it reduction ignores that the lost π bond is replaced by a second C–O bond.`,
  },
  [r`A nitrile carbon sits at the oxidation level of a {{c1::carboxylic acid}}.`]: {
    question: r`Which compound has a carbon at the same oxidation level as the C≡N carbon of propanenitrile, CH₃CH₂CN?`,
    options: [r`propanal, CH₃CH₂CHO`, r`propanoic acid, CH₃CH₂COOH`, r`1-propanol, CH₃CH₂CH₂OH`, r`carbon dioxide, CO₂`],
    correctAnswer: 1,
    explanation: r`The nitrile carbon has three bonds to nitrogen, which matches the three bonds to oxygen on a carboxyl carbon. An aldehyde carbon has two bonds to a heteroatom and an alcohol carbon one, so both are lower. Carbon dioxide has four, one level higher.`,
  },
  [r`How does hybridization of a carbon control the acidity of its C-H bond?`]: {
    question: r`Consider the three carbanions CH₃CH₂⁻, CH₂=CH⁻ and HC≡C⁻. Which is the weakest base, and why?`,
    options: [r`HC≡C⁻: its lone pair is in an sp orbital with 50% s character`, r`CH₃CH₂⁻: its lone pair is in an sp³ orbital with 25% s character`, r`CH₂=CH⁻: its lone pair is in an sp² orbital with 33% s character`, r`HC≡C⁻: its lone pair is in a pure p orbital with 0% s character`],
    correctAnswer: 0,
    explanation: r`More s character holds the lone pair closer to the nucleus and stabilizes the carbanion, so the sp carbanion is the most stable and the weakest base (its C–H has pKa about 25, against about 44 and 50). The sp² and sp³ carbanions are stronger bases. The acetylide lone pair is in an sp orbital, not a p orbital, which would give it no such stabilization.`,
  },
  [r`An alpha,beta-unsaturated ketone is electrophilic at the carbonyl carbon and also at {{c1::the beta carbon}}.`]: {
    question: r`A cysteine thiolate adds to 3-buten-2-one, CH₂=CH–CO–CH₃ (numbered C4, C3, C2, C1 as written), by conjugate (1,4) addition. The new C–S bond forms at:`,
    options: [r`C3, the CH beside the carbonyl carbon`, r`C4, the CH₂ at the end of the alkene`, r`C2, the carbon of the carbonyl group`, r`C1, the CH₃ on the carbonyl carbon`],
    correctAnswer: 1,
    explanation: r`In an α,β-unsaturated ketone, resonance places partial positive charge on the β carbon, here the terminal CH₂, so conjugate addition forms the bond there. Attack at the carbonyl carbon is direct (1,2) addition, not conjugate addition. The α carbon (C3) and the methyl carbon are not electrophilic.`,
  },
  [r`Ketoses like fructose still give a positive Benedict's test because base drives {{c1::tautomerization to an aldose}}.`]: {
    question: r`Fructose, a ketose with a free anomeric carbon, is heated with Benedict's reagent (basic Cu²⁺). What is the result, and why?`,
    options: [r`Negative: a ketone has no hydrogen that the reagent can oxidize`, r`Positive: the ketone carbon is directly oxidized to an acid`, r`Negative: fructose has no anomeric carbon that can ring-open`, r`Positive: base converts it to an aldose, which is then oxidized`],
    correctAnswer: 3,
    explanation: r`Under the basic conditions the ketose tautomerizes through an enediol to an aldose, and the aldehyde is oxidized, so the test is positive. A ketone itself is not oxidized by Cu²⁺, which is why the direct-oxidation reason is wrong even though the result is positive. The negative choices ignore the isomerization and the free anomeric carbon stated in the question.`,
  },
  [r`What functional group interconversion happens at the isomerase steps of glycolysis?`]: {
    question: r`Triose phosphate isomerase converts dihydroxyacetone phosphate (ketone at C2, primary alcohol at C1) to glyceraldehyde 3-phosphate (aldehyde at C1, secondary alcohol at C2). Does the enzyme need NAD⁺ or NADH?`,
    options: [r`Yes: C1 is oxidized, so NAD⁺ must accept a hydride`, r`Yes: C2 is reduced, so NADH must donate a hydride`, r`No: a phosphate moves from C3 to C1 with no redox`, r`No: an enediol shifts the carbonyl with no net redox`],
    correctAnswer: 3,
    explanation: r`A ketone plus a neighboring primary alcohol become an aldehyde plus a secondary alcohol through an enediol intermediate. One carbon goes up a level and its neighbor goes down, so the molecule as a whole is neither oxidized nor reduced and no cofactor is needed. The phosphate stays on C3 throughout.`,
  },
  [r`Ethers are poor hydrogen-bond {{c1::donors}} but good {{c2::acceptors}}.`]: {
    question: r`Dimethyl ether (CH₃OCH₃) is examined as a pure liquid and as a solution in water. Which description of its hydrogen bonding is correct?`,
    options: [r`None in the pure ether; in water its oxygen accepts them`, r`Some in the pure ether; in water its C–H bonds donate them`, r`None in the pure ether and none in water, as it lacks O–H`, r`Some in the pure ether and in water, as its oxygen donates`],
    correctAnswer: 0,
    explanation: r`An ether has no O–H, so its molecules cannot donate hydrogen bonds to one another, which is why ethers boil low. The oxygen lone pairs can still accept hydrogen bonds from water's O–H, which is why small ethers dissolve in water. C–H bonds are not hydrogen-bond donors, and an oxygen with no hydrogen cannot donate.`,
  },
  [r`How do you tell a phosphate ester from a phosphoanhydride, and why does the difference matter?`]: {
    question: r`ATP has three phosphates in a row (α, β, γ), with the α phosphate attached to the 5′ carbon of ribose. How many phosphoanhydride and phosphate ester linkages does ATP contain?`,
    options: [r`2 phosphoanhydride linkages and 1 phosphate ester`, r`1 phosphoanhydride linkage and 2 phosphate esters`, r`3 phosphoanhydride linkages and 0 phosphate esters`, r`0 phosphoanhydride linkages and 3 phosphate esters`],
    correctAnswer: 0,
    explanation: r`An anhydride is P–O–P and an ester is P–O–C. The α–β and β–γ links are P–O–P, so there are two anhydrides, and the α phosphate to ribose link is P–O–C, the one ester. Counting three anhydrides treats the ribose link as high-energy, and the other counts confuse the two linkage types.`,
  },
  [r`How do you recognize a urea versus an ordinary amide?`]: {
    question: r`Which of these compounds is a urea?`,
    options: [r`CH₃–CO–NHCH₃, carbonyl between C and N`, r`CH₃O–CO–NHCH₃, carbonyl between O and N`, r`CH₃O–CO–OCH₃, carbonyl between O and O`, r`H₂N–CO–NHCH₃, carbonyl between N and N`],
    correctAnswer: 3,
    explanation: r`A urea has a carbonyl flanked by two nitrogens. A carbonyl between a carbon and a nitrogen is an ordinary amide, one between an oxygen and a nitrogen is a carbamate, and one between two oxygens is a carbonate ester.`,
  },
  [r`Why does an amide absorb near 1650 cm$^{-1}$ while an ester absorbs near 1735 cm$^{-1}$?`]: {
    question: r`N-Methylacetamide and methyl acetate are examined by IR. One shows its C=O stretch near 1650 cm⁻¹ and the other near 1735 cm⁻¹. Which assignment and reason are correct?`,
    options: [r`1650 is the amide: N donation weakens its C=O bond`, r`1650 is the ester: O donation weakens its C=O bond`, r`1735 is the amide: N donation strengthens its C=O bond`, r`1735 is the amide: N withdrawal strengthens its C=O bond`],
    correctAnswer: 0,
    explanation: r`Nitrogen donates its lone pair into the carbonyl more strongly than an ester oxygen does, giving the amide C=O more single-bond character. A weaker bond vibrates at a lower frequency, so the amide is the 1650 band and the ester the 1735 band. Donation weakens the C=O rather than strengthening it, and the amide nitrogen is a donor, not a withdrawing group.`,
  },
  [r`What structural feature makes a carbohydrate a reducing sugar?`]: {
    question: r`Trehalose is a disaccharide in which C1 of one glucose is joined through oxygen to C1 of a second glucose. What result does it give with Benedict's reagent, and why?`,
    options: [r`Positive: each glucose unit keeps a free hydroxyl on C4`, r`Positive: glucose units are aldoses and always reduce Cu²⁺`, r`Negative: both anomeric carbons are locked in the acetal`, r`Negative: only ketose sugars react with Benedict's reagent`],
    correctAnswer: 2,
    explanation: r`A reducing sugar needs a free anomeric carbon, a hemiacetal that can open to an aldehyde. In trehalose both C1 carbons are used in the glycosidic bond, so neither ring can open and the test is negative, as with sucrose. Free hydroxyls elsewhere do not matter, and aldoses, not only ketoses, are what the reagent normally detects.`,
  },
  [r`Why is penicillin's beta-lactam far more reactive than an ordinary amide?`]: {
    question: r`A β-lactam (four-membered cyclic amide) and 2-piperidinone (six-membered cyclic amide) are each exposed to the active-site serine of a transpeptidase. Which acylates the serine faster, and why?`,
    options: [r`The 2-piperidinone: its larger ring holds more angle strain`, r`The β-lactam: its N donates more strongly into the C=O`, r`The β-lactam: strain and a twisted N weaken amide resonance`, r`Neither: every amide is equally inert toward a serine OH`],
    correctAnswer: 2,
    explanation: r`The four-membered ring has severe angle strain and holds nitrogen out of the plane needed for amide resonance, so the carbonyl is unusually electrophilic and ring opening releases the strain. A six-membered lactam is nearly strain-free and behaves like an ordinary, unreactive amide. Stronger nitrogen donation would make the β-lactam less reactive, not more.`,
  },
  [r`An anhydride reacts with water to give {{c1::two carboxylic acids}}, which is why anhydrides must be kept dry.`]: {
    question: r`The mixed anhydride CH₃CO–O–COCH₂CH₃ is left open to moist air. Reaction with water converts it to:`,
    options: [r`acetic acid and propanoic acid`, r`acetic acid and 1-propanol`, r`ethanol and propanoic acid`, r`acetaldehyde and propanoic acid`],
    correctAnswer: 0,
    explanation: r`Water attacks one carbonyl and expels the other half as a carboxylate, so an anhydride gives two carboxylic acids: here a two-carbon acid and a three-carbon acid. An acid plus an alcohol is what an ester gives on hydrolysis. Hydrolysis does not change oxidation level, so no aldehyde forms.`,
  },
  [r`What functional group forms when two cysteines are oxidized, and what reverses it?`]: {
    question: r`Glutathione (GSH) converts a wrongly formed protein disulfide back into two cysteine thiols. In this reaction:`,
    options: [r`the protein is oxidized and glutathione is reduced to GSSG`, r`the protein is reduced and glutathione is oxidized to GSSG`, r`the protein and glutathione are both reduced by water`, r`the protein is hydrolyzed and glutathione is unchanged`],
    correctAnswer: 1,
    explanation: r`A disulfide is the oxidized form of two thiols, so converting R–S–S–R back to two R–SH is a reduction. The electrons come from glutathione's own thiols, which pair up as the disulfide GSSG, the oxidized form. Water does not supply the electrons, and the S–S bond is cleaved by thiol exchange rather than hydrolysis.`,
  },
  [r`A cyclic ester is a {{c1::lactone}} and a cyclic amide is a {{c2::lactam}}.`]: {
    question: r`4-Hydroxybutanoic acid and 4-aminobutanoic acid can each cyclize by losing water, with the group on C4 attacking the carboxyl carbon. The five-membered products are, respectively:`,
    options: [r`a lactam and a lactone`, r`a cyclic ether and a cyclic amine`, r`a cyclic anhydride and an imine`, r`a lactone and a lactam`],
    correctAnswer: 3,
    explanation: r`An OH attacking a carboxyl carbon gives a cyclic ester, called a lactone, and an NH₂ doing the same gives a cyclic amide, a lactam. Reversing the names is the usual slip: lactam has the nitrogen. The products keep their carbonyls, so they are not simple cyclic ethers or amines, and neither is an anhydride or an imine.`,
  },
  [r`Acyl transfer potential ranks acyl phosphate {{c1::above}} thioester, which in turn far exceeds {{c2::an ordinary oxygen ester}}.`]: {
    question: r`Rank these by acyl transfer potential (free energy released on hydrolysis), highest first: acetyl-CoA, acetyl phosphate and ethyl acetate.`,
    options: [r`acetyl phosphate > acetyl-CoA > ethyl acetate`, r`acetyl-CoA > acetyl phosphate > ethyl acetate`, r`ethyl acetate > acetyl-CoA > acetyl phosphate`, r`acetyl phosphate > ethyl acetate > acetyl-CoA`],
    correctAnswer: 0,
    explanation: r`An acyl phosphate is the most activated, which is why 1,3-bisphosphoglycerate can phosphorylate ADP. A thioester such as acetyl-CoA comes next, and an ordinary oxygen ester is far less reactive. The wrong orders put the thioester on top or rank the oxygen ester above the thioester.`,
  },
  [r`A carbon bearing one OR and one OH is a {{c1::hemiacetal}}; a carbon bearing two OR groups is an {{c2::acetal}}.`]: {
    question: r`In 1,1-dimethoxyethane, CH₃CH(OCH₃)₂, carbon 1 carries two OCH₃ groups, one H and one CH₃. How is this carbon classified, and how does it behave?`,
    options: [r`Hemiacetal: reverts freely to the aldehyde in water`, r`Acetal: stable in base, and needs aqueous acid to revert`, r`Acetal: stable in acid, and needs aqueous base to revert`, r`Hemiacetal: stable in base, and needs acid to revert`],
    correctAnswer: 1,
    explanation: r`Two OR groups on one carbon make an acetal; a hemiacetal would have one OR and one OH. With no free OH, an acetal cannot fall back to the carbonyl by itself and is stable to base, but aqueous acid hydrolyzes it to acetaldehyde and methanol. The choice that swaps acid and base has the stability backward.`,
  },
  [r`Arginine's guanidinium group holds a $pK_a$ near {{c1::12.5}} because its positive charge is {{c2::delocalized over three nitrogens}}.`]: {
    question: r`An enzyme needs a side chain that stays almost fully positive even at pH 11. Which residue fits, and why?`,
    options: [r`Histidine: pKa near 6, charge spread over two nitrogens`, r`Arginine: pKa near 12.5, charge spread over three nitrogens`, r`Lysine: pKa near 10.5, charge held on a single nitrogen`, r`Glutamine: pKa near 12.5, charge held on its amide nitrogen`],
    correctAnswer: 1,
    explanation: r`Arginine's guanidinium ion is stabilized by resonance over three nitrogens, which gives it a pKa near 12.5, so it is still mostly protonated at pH 11. Histidine (pKa about 6) is neutral long before that, and lysine (pKa about 10.5) is mostly deprotonated at pH 11. Glutamine's amide nitrogen is not basic and carries no charge.`,
  },
  [r`How is a nitrile related to a carboxylic acid, and what does complete hydrolysis give?`]: {
    question: r`Benzonitrile, C₆H₅CN, is heated in aqueous acid. An intermediate can be isolated partway through, and heating longer gives the final products. These are, in order:`,
    options: [r`benzylamine, then benzoic acid and ammonium ion`, r`benzamide, then benzoic acid and ammonium ion`, r`benzamide, then benzaldehyde and ammonium ion`, r`benzaldehyde, then benzoic acid and nitrogen gas`],
    correctAnswer: 1,
    explanation: r`Water adds to the nitrile to give a primary amide, and hydrolysis of the amide gives the carboxylic acid with nitrogen released as ammonia (ammonium in acid). The carbon keeps three bonds to heteroatoms throughout, so nothing is oxidized or reduced. Benzylamine and benzaldehyde are reduction products at lower oxidation levels and cannot form here.`,
  },
  [r`Imidazole, indole, and the purine ring system are all {{c1::aromatic heterocycles}}, which makes them {{c2::planar and unusually stable}}.`]: {
    question: r`Which of these rings is NOT a planar aromatic heterocycle?`,
    options: [r`the imidazole ring of histidine`, r`the indole ring of tryptophan`, r`the pyrrolidine ring of proline`, r`the purine ring of adenine`],
    correctAnswer: 2,
    explanation: r`Imidazole, indole and purine are cyclic, fully conjugated and hold 4n+2 π electrons, so they are flat and unusually stable. Proline's pyrrolidine ring is made of sp³ carbons and an amine nitrogen with no π system, so it is a puckered, non-aromatic ring.`,
  },
  [r`Which functional group change turns a primary alcohol into a good leaving group without changing its oxidation state?`]: {
    question: r`In isoprenoid biosynthesis, an alcohol R–CH₂–OH is first converted to its diphosphate ester, R–CH₂–O–PP, and a nucleophile then displaces the oxygen from carbon. What does attaching the diphosphate accomplish?`,
    options: [r`It makes a stable anionic leaving group; carbon is not oxidized`, r`It oxidizes the carbon so that a hydride can leave in its place`, r`It makes the oxygen a stronger base, so it leaves as hydroxide`, r`It reduces the carbon so that the C–O bond breaks more easily`],
    correctAnswer: 0,
    explanation: r`Hydroxide is a very poor leaving group, but a phosphate or diphosphate ester leaves as a resonance-stabilized anion, the cell's version of a tosylate. The carbon still has one bond to oxygen, so its oxidation level is unchanged. Good leaving groups are weak bases, not strong ones.`,
  },
}
